<?php use App\Core\Auth; $ratio=(int)$stats['billed']>0?min(100,round((int)$stats['collected']/(int)$stats['billed']*100)):0; ?>
<section class="welcome"><div><span class="badge light">FINANCIAL OVERVIEW</span><h2>A clearer view of your school.</h2><p>Your students, collections and outstanding fees, all in one place.</p></div><?php if(Auth::can('payments.write')): ?><a class="button white" href="<?= e(url('invoices')) ?>">＋ Record a payment</a><?php endif ?></section>
<div class="stat-grid"><article class="stat-card"><div class="stat-label">Total fees billed <span class="stat-icon">▤</span></div><strong><small><?= e($school['currency']) ?></small> <?= money($stats['billed']) ?></strong><p><?= e($stats['invoices']) ?> active invoices</p></article><article class="stat-card"><div class="stat-label">Fees collected <span class="stat-icon green">↗</span></div><strong><small><?= e($school['currency']) ?></small> <?= money($stats['collected']) ?></strong><p class="positive"><?= e($ratio) ?>% of billed fees collected</p></article><article class="stat-card"><div class="stat-label">Outstanding balance <span class="stat-icon amber">◷</span></div><strong><small><?= e($school['currency']) ?></small> <?= money($stats['outstanding']) ?></strong><p>Across unpaid and partially paid invoices</p></article><article class="stat-card"><div class="stat-label">Total students <span class="stat-icon purple">♙</span></div><strong><?= e($studentCount) ?></strong><p>Registered in this school</p></article></div>
<div class="dashboard-grid"><section class="panel"><div class="section-heading"><div><h2>Collection activity</h2><p>Net posted payments · last six months</p></div><span class="badge neutral"><?= e($school['currency']) ?></span></div><div class="chart"><?php $max=max(1,...array_column($months,'amount')); if(!$months): ?><div class="empty">Record your first payment to see collection activity.</div><?php endif; foreach($months as $m): ?><div class="chart-row"><span><?= e(date('M Y',strtotime($m['collection_month'].'-01'))) ?></span><meter min="0" max="<?= e($max) ?>" value="<?= e($m['amount']) ?>" aria-label="<?= e($m['collection_month']) ?> collections"></meter><strong><?= money($m['amount']) ?></strong></div><?php endforeach ?></div><div class="collection-total"><span>Overall collection rate</span><strong><?= e($ratio) ?>%</strong><progress max="100" value="<?= e($ratio) ?>"></progress></div></section>
<section class="panel"><div class="section-heading"><div><h2>Student community</h2><p>Current enrollment by student type</p></div><span class="stat-icon">♙</span></div><?php foreach($types as $type): ?><div class="type-row"><span class="type-icon"><?= $type['requires_boarding']?'⌂':'☀' ?></span><div><strong><?= e($type['name']) ?></strong><small><?= $type['requires_boarding']?'Residential enrollment':'Non-residential enrollment' ?></small></div><b><?= e($type['n']) ?></b></div><?php endforeach ?><div class="note">Fees are matched to each student’s type, class, year and term.</div></section></div>
